import {API_BASE_URL, getAccessToken} from '../api/config';

export type OrderCard = {id: number; firmId: number; customer: string; statusId: number; status: string;
  amount: number; responsibleUserId: number | null; responsible: string | null; version: number;
  dueAt: string | null; deadlineCompleted: boolean};
export type OrderPage = {items: OrderCard[]; total: number; page: number; pageSize: number};
export type OrderFilters = {statuses: {id: number; name: string; company: string | null}[];
  users: {id: number; name: string; company: string | null}[];
  companies?: {id: number; name: string}[]; canSwitchCompanies?: boolean; firmId?: number | null};
export type OrderDetail = {order: OrderCard; comment?: string | null; statuses: {id: number; name: string}[]; users: {id: number; name: string}[];
  history: {id: string; userId: number | null; action: string; detail: string; createdAt: string}[];
  deadline: {dueAt: string; reminderMinutes: number; completedAt: string | null; version: number} | null};

export class TelegramApiError extends Error {
  constructor(public status: number, message: string, public reason?: 'link_required' | 'telegram_launch_required') {super(message);}
}

export const TELEGRAM_REQUEST_TIMEOUT_MS = 15000;

export async function telegramRequest<T>(path: string, options: RequestInit = {}, token: string | null = getAccessToken()): Promise<T> {
  const controller = new AbortController();
  const cancel = () => controller.abort();
  options.signal?.addEventListener('abort', cancel, {once: true});
  if (options.signal?.aborted) cancel();
  let timedOut = false;
  const timer = window.setTimeout(() => {timedOut = true; controller.abort();}, TELEGRAM_REQUEST_TIMEOUT_MS);
  try {
    const response = await fetch(`${API_BASE_URL}/telegram${path}`, {...options, signal: controller.signal, headers: {
      'Content-Type': 'application/json', ...(token ? {Authorization: `Bearer ${token}`} : {}), ...options.headers,
    }});
    const data = await response.json().catch(error => {if (controller.signal.aborted) throw error; return null;});
    if (response.status === 401 && path === '/webapp/auth' &&
        ['Подключите Telegram в личном профиле CRM.', 'Подключите Telegram заново в CRM.'].includes(data?.detail)) {
      throw new TelegramApiError(401, 'Telegram ещё не связан с вашим профилем CRM.', 'link_required');
    }
    if (response.status === 401 && path === '/webapp/auth') {
      if (data?.detail === 'Откройте приложение заново из Telegram.')
        throw new TelegramApiError(401, 'Данные запуска Telegram устарели или недействительны. Закройте это окно и снова нажмите кнопку приложения в боте.', 'telegram_launch_required');
      throw new TelegramApiError(401, data?.detail || 'Не удалось подтвердить вход из Telegram. Закройте окно и откройте приложение кнопкой бота.');
    }
    if (!response.ok) throw new TelegramApiError(response.status, response.status === 401 ? 'Откройте приложение заново из Telegram или войдите в CRM.' :
      response.status === 429 ? 'Слишком много запросов. Подождите минуту.' : data?.detail || data?.title || 'Не удалось выполнить запрос.');
    return data as T;
  } catch (error) {
    if (timedOut) throw new TelegramApiError(408, 'CRM не ответила за 15 секунд. Проверьте соединение и повторите загрузку.');
    if (error instanceof TelegramApiError) throw error;
    throw new TelegramApiError(0, 'Не удалось соединиться с CRM. Проверьте подключение к интернету и повторите.');
  } finally {window.clearTimeout(timer); options.signal?.removeEventListener('abort', cancel);}
}
export const body = (method: string, value: unknown): RequestInit => ({method, body: JSON.stringify(value)});
