import {useEffect, useState} from 'react';

type Theme = 'light' | 'dark';
const storageKey = 'vivotech.telegram.theme';
const savedTheme = (): Theme | null => {
  try {const value = localStorage.getItem(storageKey); return value === 'dark' || value === 'light' ? value : null;}
  catch {return null;}
};
const systemTheme = (): Theme => window.Telegram?.WebApp?.colorScheme ||
  (window.matchMedia?.('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');

export default function useTelegramTheme(standalone: boolean) {
  const [preference, setPreference] = useState<Theme | null>(savedTheme);
  const [automatic, setAutomatic] = useState<Theme>(systemTheme);
  const theme = preference || automatic;

  useEffect(() => {
    const app = window.Telegram?.WebApp;
    const media = window.matchMedia?.('(prefers-color-scheme: dark)');
    const update = () => setAutomatic(systemTheme());
    app?.onEvent?.('themeChanged', update);
    media?.addEventListener?.('change', update);
    return () => {app?.offEvent?.('themeChanged', update); media?.removeEventListener?.('change', update);};
  }, []);

  useEffect(() => {
    if (!standalone) return;
    const previous = document.documentElement.dataset.telegramTheme;
    document.documentElement.dataset.telegramTheme = theme;
    const color = theme === 'dark' ? '#10171f' : '#f3f6f8';
    const app = window.Telegram?.WebApp;
    try {app?.setHeaderColor?.(color); app?.setBackgroundColor?.(color); app?.setBottomBarColor?.(color);} catch { /* Older Telegram clients keep their native colors. */ }
    return () => {
      if (previous) document.documentElement.dataset.telegramTheme = previous;
      else delete document.documentElement.dataset.telegramTheme;
    };
  }, [standalone, theme]);

  const toggleTheme = () => {
    const next = theme === 'dark' ? 'light' : 'dark';
    setPreference(next);
    try {localStorage.setItem(storageKey, next);} catch { /* Theme switching also works without storage. */ }
  };
  return {theme, toggleTheme};
}
