import {FormEvent, useCallback, useEffect, useRef, useState} from 'react';
import {body, OrderDetail, OrderFilters, OrderPage, TelegramApiError, telegramRequest} from './api';
import Icon from './TelegramIcon';
import useTelegramTheme from './useTelegramTheme';
import './telegram.css';

declare global {
  interface Window {Telegram?: {WebApp?: {initData: string; ready(): void; expand(): void; colorScheme?: 'light' | 'dark';
    close?(): void; onEvent?(event: string, handler: () => void): void; offEvent?(event: string, handler: () => void): void;
    setHeaderColor?(color: string): void; setBackgroundColor?(color: string): void; setBottomBarColor?(color: string): void;
    BackButton?: {show(): void; hide(): void; onClick(handler: () => void): void; offClick(handler: () => void): void}}}}
}
const labels: Record<string, string> = {'order.comment': 'Комментарий', 'order.status_changed': 'Статус обновлён',
  'order.assigned': 'Назначен ответственный', 'order.deadline_set': 'Установлен срок', 'order.deadline_snoozed': 'Срок отложен',
  'order.deadline_completed': 'Выполнено', 'deadline.reminder_sent': 'Напоминание отправлено',
  'deadline.reminder_failed': 'Ошибка доставки', 'deadline.reminder_queued': 'Напоминание в очереди'};
const money = (value: number) => value.toLocaleString('ru-RU', {minimumFractionDigits: 2, maximumFractionDigits: 2});
const date = (value: string) => new Date(value).toLocaleString('ru-RU', {day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit'});
const initials = (name: string) => name.trim().split(/\s+/).slice(0, 2).map(word => word.replace(/[«»"'“”„]/g, '')[0] || '').join('').toUpperCase() || 'V';
const orderFromHistory = (state: {vivotechTelegramOrder?: number} | null) =>
  Number.isSafeInteger(state?.vivotechTelegramOrder) && state!.vivotechTelegramOrder! > 0 ? state!.vivotechTelegramOrder! : null;

type Session = {token: string; name: string; expiresAt?: string};

function Loading({detail = false}: {detail?: boolean}) {
  return <section className="tg-loading" aria-label={detail ? 'Загрузка заказа' : 'Загрузка заказов'}>
    <p role="status"><span className="tg-spinner"/> {detail ? 'Открываем заказ…' : 'Загружаем заказы…'}</p>
    <div className={detail ? 'tg-skeleton-detail' : 'tg-cards'} aria-hidden="true">
      {[1, 2, 3, 4].slice(0, detail ? 2 : 4).map(i => <div className="tg-skeleton" key={i}><span/><span/><span/></div>)}
    </div>
  </section>;
}

export default function TelegramWebApp({crmSession, initialFirmId = ''}: {crmSession?: Pick<Session, 'token' | 'name'>; initialFirmId?: string}) {
  // The Mini App token stays in memory and is separate from the main CRM session.
  const [session, setSession] = useState<Session | null>(null);
  const crmToken = crmSession?.token;
  const crmName = crmSession?.name;
  const {theme, toggleTheme} = useTelegramTheme(!crmToken);
  const [error, setError] = useState('');
  const [linkRequired, setLinkRequired] = useState(false);
  const [launchRequired, setLaunchRequired] = useState(false);
  const [success, setSuccess] = useState('');
  const [busy, setBusy] = useState(false);
  const [detailLoading, setDetailLoading] = useState(false);
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState('');
  const [querySearch, setQuerySearch] = useState('');
  const [filters, setFilters] = useState<OrderFilters | null>(null);
  const [firmId, setFirmId] = useState(initialFirmId);
  const [filtersExpanded, setFiltersExpanded] = useState(false);
  const [statusFilter, setStatusFilter] = useState('');
  const [responsibleFilter, setResponsibleFilter] = useState('');
  const [mine, setMine] = useState(false);
  const [overdue, setOverdue] = useState(false);
  const [orders, setOrders] = useState<OrderPage | null>(null);
  const [selectedOrderId, setSelectedOrderId] = useState<number | null>(() => orderFromHistory(window.history.state));
  const [detail, setDetail] = useState<OrderDetail | null>(null);
  const [comment, setComment] = useState('');
  const [reason, setReason] = useState('');
  const [status, setStatus] = useState('');
  const [responsible, setResponsible] = useState('');
  const [due, setDue] = useState('');
  const [interval, setIntervalMinutes] = useState(60);
  const requestId = useRef(0);
  const detailRequestId = useRef(0);
  const headingRef = useRef<HTMLHeadingElement>(null);
  const listScroll = useRef(0);
  const hasNavigated = useRef(false);
  const invalidateListRequest = useCallback(() => {requestId.current++;}, []);
  const invalidateDetailRequest = useCallback(() => {detailRequestId.current++;}, []);

  useEffect(() => {const timer = window.setTimeout(() => setQuerySearch(search), 300); return () => window.clearTimeout(timer);}, [search]);
  const fail = useCallback((e: Error) => {
    setError(e.message); setSuccess(''); setLinkRequired(false);
    if (e instanceof TelegramApiError && e.status === 401) {
      setSession(null); setOrders(null); setDetail(null); setSelectedOrderId(null);
      requestId.current++; detailRequestId.current++;
      setLaunchRequired(!crmToken);
      if (crmToken) window.dispatchEvent(new Event('vivotech:unauthorized'));
    }
  }, [crmToken]);
  useEffect(() => {
    if (!session) return;
    let active = true;
    void telegramRequest<OrderFilters>(`/orders/filters${firmId ? `?firmId=${firmId}` : ''}`, {}, session.token).then(value => {if (active) setFilters(value);}).catch(e => {if (active) fail(e);});
    return () => {active = false;};
  }, [session, firmId, fail]);
  useEffect(() => {
    if (!session?.expiresAt) return;
    const timer = window.setTimeout(() => {
      setSession(null); setOrders(null); setDetail(null); setSelectedOrderId(null);
      requestId.current++; detailRequestId.current++;
      setError('Сессия завершена. Откройте приложение заново из Telegram.');
      setLaunchRequired(true);
    }, Math.max(0, Date.parse(session.expiresAt) - Date.now()));
    return () => window.clearTimeout(timer);
  }, [session]);
  useEffect(() => {
    if (crmToken) {setSession({token: crmToken, name: crmName || ''}); return;}
    let active = true;
    setLinkRequired(false);
    setLaunchRequired(false);
    const app = window.Telegram?.WebApp;
    const botId = Number(new URLSearchParams(window.location.search).get('telegramBotId'));
    if (!app?.initData || !Number.isSafeInteger(botId) || botId <= 0) {setError('Откройте CRM кнопкой /app в личном чате с ботом.'); return;}
    app.ready(); app.expand();
    void telegramRequest<{token: string; expiresAt: string; user: {name: string}}>('/webapp/auth', body('POST', {botId, initData: app.initData}), null)
      .then(result => {if (active) setSession({token: result.token, name: result.user.name, expiresAt: result.expiresAt});})
      .catch(e => {if (active) {setError(e.message); setLinkRequired(e instanceof TelegramApiError && e.reason === 'link_required');
        setLaunchRequired(e instanceof TelegramApiError && e.reason === 'telegram_launch_required');}});
    return () => {active = false;};
  }, [crmToken, crmName]);
  const load = useCallback(async () => {
    if (!session) return;
    const query = new URLSearchParams({page: String(page), pageSize: '10', search: querySearch, mine: String(mine), overdueOnly: String(overdue)});
    if (statusFilter) query.set('statusId', statusFilter);
    if (responsibleFilter) query.set('responsibleUserId', responsibleFilter);
    if (firmId) query.set('firmId', firmId);
    const id = ++requestId.current;
    try {
      const result = await telegramRequest<OrderPage>(`/orders?${query}`, {}, session.token);
      if (id === requestId.current) setOrders(result);
    } catch (e) {if (id === requestId.current) throw e;}
  }, [session, firmId, page, querySearch, statusFilter, responsibleFilter, mine, overdue]);
  useEffect(() => {void load().catch(fail); return invalidateListRequest;}, [load, fail, invalidateListRequest]);

  const loadDetail = useCallback(async (id: number) => {
    if (!session) return;
    const request = ++detailRequestId.current;
    const value = await telegramRequest<OrderDetail>(`/orders/${id}`, {}, session.token);
    if (request !== detailRequestId.current) return;
    setDetail(value); setStatus(String(value.order.statusId)); setResponsible(String(value.order.responsibleUserId || ''));
    if (value.deadline) {
      const local = new Date(value.deadline.dueAt); local.setMinutes(local.getMinutes() - local.getTimezoneOffset());
      setDue(local.toISOString().slice(0, 16)); setIntervalMinutes(value.deadline.reminderMinutes);
    } else {setDue(''); setIntervalMinutes(60);}
  }, [session]);
  useEffect(() => {
    if (selectedOrderId === null || !session) return;
    let active = true;
    setDetail(null); setDetailLoading(true);
    void loadDetail(selectedOrderId).catch(e => {if (active) fail(e);}).finally(() => {if (active) setDetailLoading(false);});
    return () => {active = false; invalidateDetailRequest();};
  }, [selectedOrderId, session, loadDetail, fail, invalidateDetailRequest]);

  const backToOrders = useCallback(() => {
    detailRequestId.current++; setSelectedOrderId(null); setDetail(null); setError(''); setSuccess('');
    hasNavigated.current = true;
    if (orderFromHistory(window.history.state) !== null) window.history.back();
  }, []);
  useEffect(() => {
    const onPop = (event: PopStateEvent) => {
      detailRequestId.current++; setDetail(null);
      const sameCompany = !event.state?.vivotechTelegramFirmId || event.state.vivotechTelegramFirmId === (firmId || 'all');
      setSelectedOrderId(sameCompany ? orderFromHistory(event.state) : null);
      setError(''); setSuccess(''); hasNavigated.current = true;
    };
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, [firmId]);
  useEffect(() => {
    const back = window.Telegram?.WebApp?.BackButton;
    if (!back || selectedOrderId === null || !session) return;
    back.show(); back.onClick(backToOrders);
    return () => {back.offClick(backToOrders); back.hide();};
  }, [selectedOrderId, session, backToOrders]);
  useEffect(() => {
    if (!hasNavigated.current) return;
    const frame = window.requestAnimationFrame(() => {
      window.scrollTo({top: selectedOrderId === null ? listScroll.current : 0, behavior: 'auto'});
      headingRef.current?.focus({preventScroll: true});
    });
    return () => window.cancelAnimationFrame(frame);
  }, [selectedOrderId]);
  useEffect(() => {
    if (!success) return;
    const timer = window.setTimeout(() => setSuccess(''), 4000);
    return () => window.clearTimeout(timer);
  }, [success]);

  const openOrder = (id: number) => {
    listScroll.current = window.scrollY;
    hasNavigated.current = true;
    // Keep Telegram's signed launch hash and the CRM HashRouter untouched.
    window.history.pushState({...window.history.state, vivotechTelegramOrder: id, vivotechTelegramFirmId: firmId || 'all'}, '');
    setSelectedOrderId(id); setDetail(null); setError(''); setSuccess(''); setReason(''); setComment('');
  };
  const run = async (action: () => Promise<void>, message?: string) => {
    setBusy(true); setError(''); setSuccess('');
    try {await action(); if (message) setSuccess(message);} catch (e) {fail(e as Error);} finally {setBusy(false);}
  };
  const mutate = async (suffix: string, method: string, value: unknown) => {
    if (!session || !detail) return;
    await telegramRequest(`/orders/${detail.order.id}/${suffix}`, body(method, value), session.token);
    await loadDetail(detail.order.id); await load();
  };
  const submitComment = (event: FormEvent) => {
    event.preventDefault(); void run(async () => {await mutate('comments', 'POST', {text: comment}); setComment('');}, 'Комментарий добавлен');
  };
  const resetFilters = () => {setSearch(''); setQuerySearch(''); setStatusFilter(''); setResponsibleFilter(''); setMine(false); setOverdue(false); setPage(1);};
  const switchCompany = (value: string) => {
    requestId.current++; detailRequestId.current++;
    setFirmId(value); resetFilters(); setOrders(null); setDetail(null); setSelectedOrderId(null);
    setFilters(previous => previous ? {...previous, statuses: [], users: []} : null);
    setError(''); setSuccess(''); setComment(''); setReason('');
    window.history.replaceState({...window.history.state, vivotechTelegramOrder: null, vivotechTelegramFirmId: value || 'all'}, '');
  };
  const companyName = filters?.companies?.find(company => company.id === Number(firmId || filters.firmId))?.name;
  const filterCount = Number(Boolean(statusFilter)) + Number(Boolean(responsibleFilter));
  const hasFilters = Boolean(search || statusFilter || responsibleFilter || mine || overdue);
  const history = detail?.history.filter(h => labels[h.action] || h.action.startsWith('crm.')) || [];
  const pages = orders ? Math.max(1, Math.ceil(orders.total / orders.pageSize)) : 1;

  return <main className="tg-app" data-theme={theme}>
    <div className="tg-topbar">
      <div className="tg-brand"><span className="tg-brand-mark"><Icon name="grid"/></span><span>ViVoTech<span className="tg-brand-caption">CRM WORKSPACE</span></span></div>
      <div className="tg-topbar-actions">
        <button className="tg-icon-button tg-theme-toggle" onClick={toggleTheme}
          aria-label={theme === 'dark' ? 'Включить светлую тему' : 'Включить тёмную тему'} title={theme === 'dark' ? 'Светлая тема' : 'Тёмная тема'}>
          <Icon name={theme === 'dark' ? 'sun' : 'moon'}/>
        </button>
        {session && <span className="tg-avatar" title={session.name} aria-label={session.name}>{initials(session.name)}</span>}
      </div>
    </div>
    <header className="tg-header">
      {selectedOrderId !== null ? <>
        <button className="tg-back" onClick={backToOrders}><Icon name="back"/>Все заказы</button>
        <div className="tg-page-title"><div><span className="tg-eyebrow">ДЕТАЛИ ЗАКАЗА</span><h1 ref={headingRef} tabIndex={-1}>Заказ №{selectedOrderId}</h1></div><span className="tg-heading-icon"><Icon name="orders" width="27" height="27"/></span></div>
      </> : <>
        <div className="tg-welcome"><span className="tg-eyebrow">РАБОЧЕЕ ПРОСТРАНСТВО</span>{session && <span className="tg-user">{session.name}</span>}</div>
        <div className="tg-page-title"><h1 ref={headingRef} tabIndex={-1}>Заказы<span className="tg-title-dot">.</span></h1><span className="tg-live"><i/>Ваш кабинет</span></div>
        <p className="tg-subtitle">Клиенты, команда и сроки. Всё под контролем.</p>
      </>}
    </header>
    {error && <div className="tg-error" role="alert"><Icon name="activity"/><span>{error}</span></div>}
    {linkRequired && !session && <section className="tg-link-help" aria-label="Подключение Telegram">
      <h2>Подключите свой аккаунт</h2>
      <p>Войдите в серверную CRM, нажмите «Подключить Telegram», затем откройте полученную ссылку и нажмите «Старт» в боте.</p>
      <a href={`${window.location.origin}${window.location.pathname.replace(/\/telegram(?:\/index\.html)?\/?$/, '/')}#/telegram-link`} target="_blank" rel="noopener noreferrer">Открыть CRM и подключить Telegram</a>
      <p>После привязки закройте это окно и снова откройте приложение кнопкой бота.</p>
    </section>}
    {success && session && <div className="tg-toast" role="status"><Icon name="check"/>{success}</div>}
    {error && !session && (launchRequired ? <div className="tg-launch-help"><p>Привязку к CRM повторять не нужно. Откройте новое окно через меню бота или команду /app.</p>
      {window.Telegram?.WebApp?.close && <button className="tg-primary" onClick={() => window.Telegram?.WebApp?.close?.()}>Закрыть окно приложения</button>}</div> :
      <button className="tg-primary" onClick={() => window.location.reload()}><Icon name="refresh"/>Повторить загрузку</button>)}
    {!session && !error && <p className="tg-connecting" role="status"><span className="tg-spinner"/>Подключаемся к CRM…</p>}
    {session && selectedOrderId === null && <div className="tg-list-view">
      {filters?.canSwitchCompanies ? <section className="tg-company-scope" aria-label="Выбор компании">
        <label>Компания<select value={firmId} disabled={busy} onChange={event => switchCompany(event.target.value)}>
          <option value="">Все компании</option>{filters.companies?.map(company => <option key={company.id} value={company.id}>{company.name}</option>)}
        </select></label><p>{firmId ? 'Заказы и сотрудники выбранной компании' : 'Общий обзор всех доступных компаний'}</p>
      </section> : companyName && <p className="tg-company-name">Компания: <strong>{companyName}</strong></p>}
      {orders && <section className="tg-overview" aria-label="Обзор заказов">
        <div className="tg-overview-main"><span className="tg-overview-icon"><Icon name="orders"/></span><div><span className="tg-stat-label">Найдено заказов</span><strong>{orders.total.toLocaleString('ru-RU')}</strong></div><span className="tg-overview-decoration" aria-hidden="true">↗</span></div>
        <div className="tg-overview-amount"><span className="tg-stat-label">Сумма на странице</span><strong>{money(orders.items.reduce((total, order) => total + order.amount, 0))}</strong><span className="tg-stat-hint">{orders.items.length} из {orders.total} заказов</span></div>
      </section>}
      <section className="tg-filter-area" aria-label="Фильтры заказов">
        <div className="tg-search-row"><label className="tg-search"><span className="tg-sr-only">Клиент или номер</span><Icon name="search"/>
          <input type="search" placeholder="Клиент или номер заказа" value={search} maxLength={100} onChange={e => {setSearch(e.target.value); setPage(1);}}/>
        </label><button className={`tg-filter-button ${filtersExpanded || filterCount ? 'is-active' : ''}`} onClick={() => setFiltersExpanded(value => !value)} aria-expanded={filtersExpanded} aria-controls="tg-advanced-filters"><Icon name="filters"/><span>Фильтры</span>{filterCount > 0 && <b>{filterCount}</b>}</button></div>
        <div className="tg-quick-filters"><button className={`tg-chip ${!mine && !overdue ? 'is-active' : ''}`} onClick={() => {setMine(false); setOverdue(false); setPage(1);}}>Все заказы</button>
          <label className={`tg-chip ${mine ? 'is-active' : ''}`}><input type="checkbox" checked={mine} onChange={e => {setMine(e.target.checked); setPage(1);}}/><Icon name="user"/>Мои заказы</label>
          <label className={`tg-chip ${overdue ? 'is-active' : ''}`}><input type="checkbox" checked={overdue} onChange={e => {setOverdue(e.target.checked); setPage(1);}}/><Icon name="clock"/>Просроченные</label>
        </div>
        {filtersExpanded && <div className="tg-advanced-filters" id="tg-advanced-filters">
          <label>Фильтр по статусу<select value={statusFilter} onChange={e => {setStatusFilter(e.target.value); setPage(1);}}><option value="">Все статусы</option>
            {filters?.statuses?.map(s => <option key={s.id} value={s.id}>{s.name}{s.company ? ` · ${s.company}` : ''}</option>)}</select></label>
          <label>Фильтр по ответственному<select value={responsibleFilter} onChange={e => {setResponsibleFilter(e.target.value); setPage(1);}}><option value="">Все сотрудники</option>
            {filters?.users?.map(u => <option key={u.id} value={u.id}>{u.name}{u.company ? ` · ${u.company}` : ''}</option>)}</select></label>
        </div>}
      </section>
      <div className="tg-list-heading"><div><h2>Список заказов</h2>{hasFilters && <button className="tg-text-button" onClick={resetFilters}>Сбросить фильтры<Icon name="close" width="13" height="13"/></button>}</div>
        <button className={`tg-icon-button ${busy ? 'is-refreshing' : ''}`} disabled={busy} onClick={() => void run(load)} aria-label="Обновить" title="Обновить заказы"><Icon name="refresh"/></button></div>
      {!orders && !error && <Loading/>}
      {!orders && error && <button className="tg-secondary" disabled={busy} onClick={() => void run(load)}><Icon name="refresh"/>Повторить загрузку</button>}
      {orders && <>
        <section className="tg-cards" aria-label="Список заказов">{orders.items.map(order => {
          const late = Boolean(order.dueAt && !order.deadlineCompleted && Date.parse(order.dueAt) < Date.now());
          return <button className="tg-order" key={order.id} disabled={busy} onClick={() => openOrder(order.id)}>
            <span className="tg-order-top"><span className="tg-order-number">ЗАКАЗ <b>#{order.id}</b></span><span className={`tg-status tg-status-${order.statusId % 5}`}><i/>{order.status}</span></span>
            <span className="tg-order-customer"><span className="tg-customer-avatar">{initials(order.customer)}</span><strong>{order.customer}</strong></span>
            {filters?.canSwitchCompanies && !firmId && <span className="tg-order-company">{filters.companies?.find(company => company.id === order.firmId)?.name}</span>}
            <span className="tg-order-meta"><span><Icon name="user" width="15" height="15"/>{order.responsible || 'Без ответственного'}</span>
              {order.dueAt && <span className={`tg-due ${late ? 'is-overdue' : ''} ${order.deadlineCompleted ? 'is-complete' : ''}`}><Icon name={order.deadlineCompleted ? 'check' : 'clock'} width="15" height="15"/>{date(order.dueAt)}{late ? ' · просрочен' : order.deadlineCompleted ? ' · выполнен' : ''}</span>}</span>
            <span className="tg-order-bottom"><span className="tg-order-amount"><small>Сумма заказа</small><b>{money(order.amount)}</b></span><span className="tg-open-order">Открыть заказ<span><Icon name="arrow" width="17" height="17"/></span></span></span>
          </button>;
        })}</section>
        {orders.total === 0 && <div className="tg-empty"><span><Icon name="search" width="30" height="30"/></span><h3>Здесь пока пусто</h3><p>{hasFilters ? 'Попробуйте другой запрос или сбросьте фильтры.' : 'Доступные вам заказы появятся здесь.'}</p>{hasFilters && <button className="tg-primary" onClick={resetFilters}>Показать все заказы<Icon name="arrow"/></button>}</div>}
        {orders.total > 0 && <nav className="tg-pagination" aria-label="Страницы"><button className="tg-icon-button" disabled={page <= 1 || busy} onClick={() => setPage(p => p - 1)} aria-label="Предыдущая страница"><Icon name="back"/></button><span>Страница <b>{page}</b> из {pages}</span>
          <button className="tg-icon-button" disabled={page >= pages || busy} onClick={() => {setPage(p => p + 1); window.scrollTo({top: 0, behavior: 'smooth'});}} aria-label="Следующая страница"><Icon name="arrow"/></button></nav>}
      </>}
    </div>}
    {session && selectedOrderId !== null && <div className="tg-detail-view">
      {detailLoading && <Loading detail/>}
      {!detailLoading && !detail && error && <button className="tg-primary" disabled={busy} onClick={() => void run(() => loadDetail(selectedOrderId))}><Icon name="refresh"/>Повторить загрузку заказа</button>}
      {detail && <>
        <section className="tg-detail-hero" aria-label="Информация о заказе">
          <div className="tg-detail-hero-top"><span className="tg-eyebrow">КЛИЕНТ</span><span className={`tg-status tg-status-${detail.order.statusId % 5}`}><i/>{detail.order.status}</span></div>
          <h2>{detail.order.customer}</h2><div className="tg-detail-amount"><span>Сумма заказа</span><strong>{money(detail.order.amount)}</strong></div>
          <div className="tg-detail-facts"><div><Icon name="user"/><span>Ответственный<strong>{detail.order.responsible || 'Не назначен'}</strong></span></div><div><Icon name="calendar"/><span>Срок<strong>{detail.deadline ? date(detail.deadline.dueAt) : 'Не установлен'}</strong></span></div></div>
          {detail.comment && <p className="tg-order-note">{detail.comment}</p>}
        </section>
        <div className="tg-detail-grid">
          <section className="tg-panel tg-detail-panel"><div className="tg-section-heading"><span className="tg-section-icon"><Icon name="activity"/></span><div><h2>Статус заказа</h2><p>Следующий шаг в работе</p></div></div>
            <form onSubmit={e => {e.preventDefault(); void run(async () => {await mutate('status', 'PUT', {statusId: Number(status), version: detail.order.version, reason}); setReason('');}, 'Статус обновлён');}}>
              <label>Статус<select value={status} onChange={e => setStatus(e.target.value)}>{detail.statuses.map(s => <option value={s.id} key={s.id}>{s.name}</option>)}</select></label>
              <label>Причина перехода<input required maxLength={1000} placeholder="Что изменилось в заказе?" value={reason} onChange={e => setReason(e.target.value)}/></label>
              <button className="tg-primary" disabled={busy}>Сменить статус<Icon name="arrow"/></button>
            </form>
          </section>
          <section className="tg-panel tg-detail-panel"><div className="tg-section-heading"><span className="tg-section-icon tg-section-icon-blue"><Icon name="user"/></span><div><h2>Команда</h2><p>Кто ведёт этот заказ</p></div></div>
            <form onSubmit={e => {e.preventDefault(); void run(() => mutate('responsible', 'PUT', {userId: Number(responsible), version: detail.order.version}), 'Ответственный назначен');}}>
              <label>Ответственный<select required value={responsible} onChange={e => setResponsible(e.target.value)}><option value="">Выберите сотрудника</option>{detail.users.map(u => <option value={u.id} key={u.id}>{u.name}</option>)}</select></label>
              <button className="tg-secondary" disabled={busy}>Назначить<Icon name="check"/></button>
            </form>
          </section>
          <section className="tg-panel tg-detail-panel tg-deadline-panel"><div className="tg-section-heading"><span className="tg-section-icon tg-section-icon-amber"><Icon name="calendar"/></span><div><h2>Срок и напоминания</h2><p>{detail.deadline?.completedAt ? 'Задача выполнена' : 'Поможем ничего не упустить'}</p></div></div>
            <form onSubmit={e => {e.preventDefault(); void run(() => mutate('deadline', 'PUT', {dueAt: new Date(due).toISOString(), reminderMinutes: interval, version: detail.order.version}), 'Срок сохранён');}}>
              <div className="tg-form-row"><label>Срок<input required type="datetime-local" value={due} onChange={e => setDue(e.target.value)}/></label><label>Напоминать каждые, мин.<input required type="number" min={1} max={10080} value={interval} onChange={e => setIntervalMinutes(Number(e.target.value))}/></label></div>
              <button className="tg-secondary" disabled={busy}>Сохранить срок<Icon name="check"/></button>
            </form>
            {detail.deadline && !detail.deadline.completedAt && <div className="tg-deadline-actions"><button disabled={busy} onClick={() => void run(() => mutate('deadline/snooze', 'POST', {version: detail.deadline!.version}), 'Напоминание отложено на час')}><Icon name="clock"/>Отложить на час</button><button className="tg-success" disabled={busy} onClick={() => void run(() => mutate('deadline/complete', 'POST', {version: detail.deadline!.version}), 'Отмечено выполненным')}><Icon name="check"/>Отметить выполненным</button></div>}
          </section>
          <section className="tg-panel tg-detail-panel"><div className="tg-section-heading"><span className="tg-section-icon tg-section-icon-blue"><Icon name="message"/></span><div><h2>Заметка для команды</h2><p>Сохраните важное в истории</p></div></div>
            <form onSubmit={submitComment}><label>Комментарий<textarea required maxLength={4000} placeholder="Договорённости, детали или следующий шаг…" value={comment} onChange={e => setComment(e.target.value)}/></label><button className="tg-primary" disabled={busy}>Добавить комментарий<Icon name="arrow"/></button></form>
          </section>
        </div>
        <section className="tg-panel tg-history-panel"><div className="tg-section-heading"><span className="tg-section-icon"><Icon name="clock"/></span><div><h2>История заказа</h2><p>Все изменения в одном месте</p></div><span className="tg-history-count">{history.length}</span></div>
          {history.length > 0 ? <ol className="tg-history">{history.map(h => <li key={h.id}><span className="tg-timeline-dot"/><div><div className="tg-history-title"><strong>{labels[h.action] || 'Изменение в CRM'}</strong><time dateTime={h.createdAt}>{date(h.createdAt)}</time></div><p>{h.detail}</p><small>{h.userId ? `Пользователь ${h.userId}` : 'CRM'}</small></div></li>)}</ol> : <p className="tg-history-empty">Здесь появятся комментарии и изменения заказа.</p>}
        </section>
      </>}
    </div>}
    <footer className="tg-footer"><span className="tg-footer-dot"/>ViVoTech CRM<span>Ваш рабочий ритм</span></footer>
  </main>;
}
